"""Offline regression coverage for missing dimensions in transpose."""

import numpy as np
import pytest

from xarray import DataArray
from xarray.testing import assert_identical


@pytest.fixture(params=["dataarray", "dataset", "variable"])
def transpose_object(request):
    array = DataArray(
        np.arange(24).reshape(2, 3, 4),
        dims=("time", "lat", "lon"),
        coords={
            "time": [0, 1],
            "lat": [10, 20, 30],
            "lon": [0, 1, 2, 3],
            "grid": (("lat", "lon"), np.arange(12).reshape(3, 4)),
            "scalar": 42,
        },
        name="air",
    )
    if request.param == "dataset":
        return array.to_dataset()
    if request.param == "variable":
        return array.variable
    return array


@pytest.mark.parametrize("dims", [
    ("not_existing_dim", "lat", "lon", "time", ...),
    ("lat", ..., "not_existing_dim", "time"),
    (..., "not_existing_dim", "time"),
    ("not_existing_dim", "lat", "lon", "time"),
])
def test_transpose_missing_dimension_raises(transpose_object, dims):
    with pytest.raises(ValueError, match="not_existing_dim.*do not exist"):
        transpose_object.transpose(*dims)


@pytest.mark.parametrize("policy", ["warn", "ignore"])
@pytest.mark.parametrize("dims", [
    ("not_existing_dim", "lat", "lon", "time", ...),
    ("lat", ..., "not_existing_dim", "time"),
    (..., "not_existing_dim", "time"),
    ("not_existing_dim", "lat", "lon", "time"),
])
def test_transpose_missing_dimension_policy(transpose_object, dims, policy):
    expected = transpose_object.transpose("lat", "lon", "time")
    if policy == "warn":
        with pytest.warns(UserWarning, match="not_existing_dim.*do not exist") as caught:
            actual = transpose_object.transpose(*dims, missing_dims=policy)
        assert len(caught) == 1
    else:
        actual = transpose_object.transpose(*dims, missing_dims=policy)
    assert_identical(actual, expected)


def test_transpose_missing_dimension_still_requires_all_dimensions(transpose_object):
    with pytest.raises(ValueError, match="permuted"):
        transpose_object.transpose("lat", "not_existing_dim", missing_dims="ignore")

